import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Static Hermes Runtime","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/static-hermes-runtime/README.md"},"headers":[],"relativePath":"tools/static-hermes-runtime/README.md","filePath":"tools/static-hermes-runtime/README.md","lastUpdated":1792508790000}`),a={name:`tools/static-hermes-runtime/README.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="static-hermes-runtime" tabindex="-1">Static Hermes Runtime <a class="header-anchor" href="#static-hermes-runtime" aria-label="Permalink to “Static Hermes Runtime”">​</a></h1><p><a href="https://www.npmjs.com/package/@pumpkin-plugins/static-hermes-runtime" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/%40pumpkin-plugins%2Fstatic-hermes-runtime" alt="npm downloads"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/static-hermes-runtime" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/v/%40pumpkin-plugins%2Fstatic-hermes-runtime?label=latest%20release" alt="latest npm release"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/static-hermes-runtime" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/l/%40pumpkin-plugins%2Fstatic-hermes-runtime" alt="npm license"></a></p><p>This package supplies the Static Hermes backend for Pumpkin plugin components. It compiles bundled JavaScript to Hermes bytecode by default. Pass <code>--parse-ts</code> to parse a TypeScript bundle; Hermes marks that parser partial and unstable. The compiler links the bytecode with Hermes, the JSI shim, and generated Pumpkin/WASI bindings into a WebAssembly component. Static Hermes is the default engine, with QuickJS available as an alternative.</p><p>Start with the <a href="./docs/">runtime documentation</a>. This README covers toolchain setup, build profiles, compiler and linker flags, and API coverage. The <a href="/pumpkin-plugins/guides/benchmarking">benchmarking guide</a> compares the engines.</p><h2 id="prepare-hermes" tabindex="-1">Prepare Hermes <a class="header-anchor" href="#prepare-hermes" aria-label="Permalink to “Prepare Hermes”">​</a></h2><p><code>prepare-hermes</code> prebuilds Hermes and its WASI runtime libraries. It needs Git, CMake, Ninja, a host C/C++ compiler, and a WASI SDK. The command resolves the pinned WASI SDK automatically unless <code>STATIC_HERMES_WASI_SDK_PATH</code>, <code>WASI_SDK_PATH</code>, or <code>WASI_SDK</code> points to a valid installation. It reuses a valid cached SDK when no path is configured; an incomplete cached SDK is replaced automatically. Concurrent setup processes share one SDK installation. If no valid cache exists, <code>curl</code> and <code>tar</code> must be available to download and extract the pinned SDK. It does not install <code>wit-bindgen</code> or <code>wasm-tools</code>, so Rust/Cargo is not needed for this preparation command.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/static-hermes-runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare-hermes</span></span></code></pre></div><p>Preparation uses the SDK release and platform SHA-256 pins in <code>wasi-sdk.lock.json</code>. Release metadata must report the same digest before download, and the downloaded archive is checked against the local pin. It caches the SDK under <code>.cache/hermes/</code> by default. It checks out the source commit in <code>hermes-source.lock.json</code>, applies the ordered patches in <code>hermes-patches/</code>, then builds host <code>hermesc</code> and the full and lean WASI 2 Hermes/JSI libraries.</p><p>The cache is reused while its source pin, patches, toolchain, and build settings match. A changed input triggers a rebuild. The WASI build directory keeps its own copy of the CMake toolchain file, so a shared cache keeps working after the runtime package moves, is upgraded or is reinstalled. Preparation refreshes the managed checkout when the source pin changes and rejects local Hermes source changes outside the managed patch set. Concurrent preparations lock the cache, source checkout, host build directory, and WASI build directory by resolved path, so separate workspaces that share any of those directories serialize. Toolchain setup takes its own lock on <code>toolchain/</code> inside the cache and reuses valid cached tools without locking, so it does not wait for a Hermes build.</p><p>Plugin builds prepare Hermes automatically when <code>engine</code> is omitted or set to <code>&quot;static-hermes&quot;</code>. Run the command above to prewarm Hermes or prepare it explicitly before a build. A full component build also resolves the pinned <code>wit-bindgen</code> and <code>wasm-tools</code> versions from <code>toolchain-versions.json</code> and sets them up automatically. If <code>WASM_TOOLS</code> is unset and no valid cached binary is available, setup downloads the platform archive pinned in <code>wasm-tools.lock.json</code>, checks its SHA-256 digest, and replaces an invalid cache entry. A valid <code>WIT_BINDGEN</code> override, shared-cache binary, or <code>~/.cargo/bin/wit-bindgen</code> is reused. Without a <code>WIT_BINDGEN</code> override, setup skips a <code>~/.cargo/bin/wit-bindgen</code> that reports another version. With no matching cached or user-installed executable, it installs the pinned <code>wit-bindgen</code> into the shared cache and needs Rust/Cargo (using the pinned Rust toolchain through <code>rustup</code> when available). A <code>WIT_BINDGEN</code> or <code>WASM_TOOLS</code> override that reports the wrong version fails setup.</p><p>The WASI SDK, Hermes source, and toolchain version pins follow the <a href="https://raw.githubusercontent.com/filiphsps/pumpkin-plugins/master/schemas/wasi-sdk-release-pin.schema.json" target="_blank" rel="noreferrer">WASI SDK release pin schema</a>, <a href="https://raw.githubusercontent.com/filiphsps/pumpkin-plugins/master/schemas/upstream-git-pin.schema.json" target="_blank" rel="noreferrer">upstream Git pin schema</a>, and <a href="https://raw.githubusercontent.com/filiphsps/pumpkin-plugins/master/schemas/toolchain-versions.schema.json" target="_blank" rel="noreferrer">toolchain versions schema</a>. The package also carries the WASI Preview 2 CMake toolchain adjustment required by Hermes. Optional paths and build settings are listed under <a href="#build-flags">Build flags</a>.</p><p>The external-consumer CI check uses these tool versions:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Version</th></tr></thead><tbody><tr><td>Node.js</td><td><code>24.21.0</code></td></tr><tr><td>pnpm</td><td><code>12.11.2</code></td></tr><tr><td>CMake</td><td><code>4.4.4</code></td></tr><tr><td>Ninja</td><td><code>1.13.2</code></td></tr><tr><td>Rust and Cargo</td><td><code>1.99.0</code></td></tr><tr><td>wit-bindgen</td><td><code>0.62.0</code></td></tr><tr><td>wasm-tools</td><td><code>1.261.0</code></td></tr><tr><td>WASI SDK</td><td><code>34</code></td></tr><tr><td>Windows x64 MSVC toolset</td><td><code>14.44</code></td></tr></tbody></table><p>Set <code>STATIC_HERMES_CACHE_DIR</code> to change the default <code>.cache/hermes/</code> location. The packed-consumer check keeps its pnpm store in a temporary directory outside the consumer&#39;s <code>node_modules</code>.</p><h2 id="cli-and-package-api" tabindex="-1">CLI and package API <a class="header-anchor" href="#cli-and-package-api" aria-label="Permalink to “CLI and package API”">​</a></h2><p>The package CLI is compiled from <code>src/cli.ts</code> to <code>dist/cli.js</code> and registered as <code>static-hermes-runtime</code>. Run it from this monorepo with:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/static-hermes-runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/static-hermes-runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static-hermes-runtime</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>Package consumers can import <code>buildStaticHermesComponent</code>, <code>prepareHermes</code>, and the other public runtime functions directly from <code>@pumpkin-plugins/static-hermes-runtime</code>. The <code>codegen analyze</code> and <code>codegen generate</code> commands take prepared WIT inputs and do not read a JavaScript bundle. Use <code>--api-methods</code> and <code>--wasi-methods</code> to select operation identifiers; when omitted, codegen includes all operations in the selected interfaces. <code>--event-types</code> selects event variants the same way it does for <code>component build</code>, so codegen output matches a build&#39;s event selection. <code>component build</code> accepts a JavaScript bundle by default; pass <code>--parse-ts</code> with a TypeScript bundle, or set <code>parseTypeScript: true</code> in <code>buildStaticHermesComponent</code>. Hermes marks TypeScript parser support partial and unstable. Set <code>quietOutput: true</code> on <code>buildStaticHermesComponent</code> when a caller owns the console format; runtime stdout is suppressed, while command failures retain stderr diagnostics.</p><h2 id="engine-and-runtime-profiles" tabindex="-1">Engine and runtime profiles <a class="header-anchor" href="#engine-and-runtime-profiles" aria-label="Permalink to “Engine and runtime profiles”">​</a></h2><p>Omitting <code>engine</code> selects Static Hermes. Set <code>&quot;engine&quot;: &quot;quickjs&quot;</code> in the package&#39;s <code>pumpkinPlugin</code> configuration to select QuickJS.</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pumpkinPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;entry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/plugin.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build/plugin.wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;wasi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;staticHermesRuntime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;full&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;staticHermesGc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;malloc&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Static Hermes defaults to the lean profile and Hades garbage collection. Both profiles execute precompiled Hermes bytecode; full also retains runtime source compilation, including <code>eval</code> and the <code>Function</code> constructor. Set <code>staticHermesRuntime</code> to <code>&quot;full&quot;</code> to use it. Set <code>staticHermesGc</code> to <code>&quot;malloc&quot;</code> to use malloc-managed GC. Both settings require the Static Hermes engine and cannot be combined with QuickJS. The wasm32 WASI build has threads disabled, so Hades uses incremental collection.</p><p>To build your plugin, replace <code>my-plugin</code> with its package name from <code>package.json</code>:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/my-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Static Hermes builds prepare the toolchain automatically when required.</p><h2 id="production-and-development-builds" tabindex="-1">Production and development builds <a class="header-anchor" href="#production-and-development-builds" aria-label="Permalink to “Production and development builds”">​</a></h2><p>Production builds minify the JavaScript bundle, compile it to optimized Hermes bytecode with function names and debug information stripped, and compile the native WASI code with <code>-Oz</code>. Function/data sections allow unused code to be removed at link time. The linker strips symbols from the production component. The shared build tool warns when the component is larger than 5 MiB (5,242,880 bytes) and fails the build instead when <code>PUMPKIN_PLUGINS_FAIL_ON_SIZE_LIMIT=1</code> is set.</p><p>Development builds keep the JavaScript bundle readable and retain Hermes source locations and native line tables for backtraces. Native code remains size optimized. The specific compiler and linker flags are listed below.</p><h2 id="build-flags" tabindex="-1">Build flags <a class="header-anchor" href="#build-flags" aria-label="Permalink to “Build flags”">​</a></h2><p>These settings cover the build tools and paths, Hermes library configuration, Hermes bytecode compilation, and WASI C/C++ compilation and linking.</p><h3 id="toolchain-paths" tabindex="-1">Toolchain paths <a class="header-anchor" href="#toolchain-paths" aria-label="Permalink to “Toolchain paths”">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><code>STATIC_HERMES_WASI_SDK_PATH</code></td><td>Optional WASI SDK path override. Otherwise setup reuses <code>WASI_SDK_PATH</code> or <code>WASI_SDK</code>, or selects the matching archive from <code>wasi-sdk.lock.json</code>, checks its published digest against the lock, verifies the downloaded archive, and caches it under <code>.cache/hermes/toolchain/</code>.</td></tr><tr><td><code>STATIC_HERMES_CACHE_DIR</code></td><td>Cache root override. By default, Static Hermes uses <code>.cache/hermes/</code> under the nearest pnpm workspace containing the consumer project directory, or under that directory for standalone projects.</td></tr><tr><td><code>STATIC_HERMES_SOURCE_DIR</code></td><td>Hermes checkout; defaults to <code>source/</code> under the cache root.</td></tr><tr><td><code>STATIC_HERMES_HOST_BUILD_DIR</code></td><td>Host build directory; defaults to <code>build-host/</code> under the cache root.</td></tr><tr><td><code>STATIC_HERMES_WASI_BUILD_DIR</code></td><td>Hades WASI build directory; defaults to <code>build-wasip2/</code> under the cache root. The malloc build uses a sibling directory with the <code>-malloc</code> suffix.</td></tr><tr><td><code>WIT_BINDGEN</code></td><td>Optional <code>wit-bindgen</code> path override. The override must report the pinned <code>tools.wit-bindgen</code> version from <code>toolchain-versions.json</code>; a mismatch fails setup. Without it, setup reuses a matching cached or <code>~/.cargo/bin/wit-bindgen</code> executable, or installs the pinned version into the shared cache.</td></tr><tr><td><code>WASM_TOOLS</code></td><td>Optional <code>wasm-tools</code> path override for component builds and WIT analysis. It must report the pinned <code>tools.wasm-tools</code> version from <code>toolchain-versions.json</code>; otherwise setup reuses a valid cache or downloads and replaces an invalid cached executable.</td></tr></tbody></table><h3 id="hermes-configuration" tabindex="-1">Hermes configuration <a class="header-anchor" href="#hermes-configuration" aria-label="Permalink to “Hermes configuration”">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><code>HERMES_ENABLE_TOOLS=ON</code> on the host build</td><td>Builds <code>shermes</code>; the host executable is not included in plugins.</td></tr><tr><td>Host C/C++ Release flags <code>-Os -DNDEBUG</code></td><td>Reduces local compiler-tool size and removes assertions; it does not change plugin components.</td></tr><tr><td><code>-Wno-unused-template</code> in host Release and WASI MinSizeRel C++ flags</td><td>Suppresses unused function template warnings from upstream Hermes sources; it does not affect compiled output.</td></tr><tr><td><code>HERMES_ENABLE_TOOLS=OFF</code> on the WASI build</td><td>Excludes build tools from the runtime.</td></tr><tr><td><code>HERMES_ENABLE_NAPI=OFF</code></td><td>Excludes the Node API.</td></tr><tr><td><code>HERMES_ENABLE_TEST_SUITE=OFF</code></td><td>Skips test targets in the runtime build.</td></tr><tr><td><code>HERMES_ENABLE_DEBUGGER=OFF</code></td><td>Excludes debugger support.</td></tr><tr><td><code>HERMES_ENABLE_INTL=OFF</code></td><td>Excludes Intl APIs and their locale data.</td></tr><tr><td><code>HERMES_BUILD_SHARED_JSI=OFF</code></td><td>Keeps JSI in the static link.</td></tr><tr><td><code>HERMESVM_ALLOW_JIT=0</code></td><td>Disables the JIT, which is not used by WASI components.</td></tr><tr><td><code>HERMES_UNICODE_LITE=ON</code></td><td>Uses Hermes&#39;s reduced Unicode implementation.</td></tr><tr><td><code>HERMES_ENABLE_CORE_EXTENSIONS=OFF</code>, <code>HERMES_ENABLE_CONTRIB_EXTENSIONS=OFF</code></td><td>Omits optional JSI extensions. <code>STATIC_HERMES_ENABLE_JSI_EXTENSIONS=1</code> enables both and changes component size; measure the production component after changing it.</td></tr><tr><td><code>HERMES_ENABLE_UNICODE_REGEXP_PROPERTY_ESCAPES=ON</code></td><td>Keeps <code>\\p{...}</code> and <code>\\P{...}</code> regexp support. <code>STATIC_HERMES_ENABLE_UNICODE_REGEXP_PROPERTY_ESCAPES=0</code> removes that support and can reduce component size.</td></tr><tr><td><code>HERMES_CHECK_NATIVE_STACK=ON</code></td><td>Converts native recursion overflow into a catchable JavaScript <code>RangeError</code>; the comparison checks this for full and lean builds.</td></tr><tr><td><code>HERMES_ALLOW_BOOST_CONTEXT=0</code></td><td>Avoids Boost.Context, which is unavailable on this WASI target.</td></tr><tr><td><code>HERMESVM_GCKIND=HADES</code></td><td>Default collector. With threads disabled on this wasm32 WASI target, Hades uses incremental collection.</td></tr><tr><td><code>HERMESVM_GCKIND=MALLOC</code></td><td>Selects malloc-managed GC for WASI. Set <code>pumpkinPlugin.staticHermesGc</code> to <code>&quot;malloc&quot;</code> to choose it.</td></tr><tr><td><code>STATIC_HERMES_ENABLE_LEAN_ARCHIVE=0</code></td><td>Links the full runtime profile instead of lean. In plugin builds it overrides <code>pumpkinPlugin.staticHermesRuntime</code>; <code>buildStaticHermesComponent</code> uses it only when <code>runtimeVariant</code> is omitted.</td></tr></tbody></table><h3 id="javascript-to-c-compiler" tabindex="-1">JavaScript-to-C compiler <a class="header-anchor" href="#javascript-to-c-compiler" aria-label="Permalink to “JavaScript-to-C compiler”">​</a></h3><p>Production runs <code>hermesc -color -O4 -fstrip-function-names -g0 -emit-binary</code>:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>-color</code></td><td>Prints colored compiler diagnostics in build logs. The build always passes this flag, including development builds.</td></tr><tr><td><code>-parse-ts</code></td><td>Optional. Parses supported TypeScript syntax in a TypeScript bundle by converting it to Flow; upstream support is partial and unstable.</td></tr><tr><td><code>-Og</code></td><td>Applies Hermes optimizations intended to remain suitable for debugging; used in development.</td></tr><tr><td><code>-O4</code></td><td>Optimizes Hermes bytecode.</td></tr><tr><td><code>-fstrip-function-names</code></td><td>Removes function names from the generated string table.</td></tr><tr><td><code>-g0</code></td><td>Omits compiler debug information.</td></tr><tr><td><code>-g1</code></td><td>Keeps Hermes source locations for JavaScript backtraces without per-instruction debug data.</td></tr><tr><td><code>-emit-binary</code></td><td>Emits Hermes bytecode embedded in the component.</td></tr></tbody></table><p>Development uses <code>hermesc -color -Og -g1 -emit-binary</code>: the bundle stays non-minified, function names remain, and Hermes keeps source locations for JavaScript backtraces. Native C/C++ compilation uses <code>-Oz -gline-tables-only -DNDEBUG -ffunction-sections -fdata-sections</code>; this keeps native line tables and function names while minimizing code and allowing unused sections to be removed. Development components retain those line tables; the linker does not use <code>--strip-debug</code> or <code>--strip-all</code>.</p><h3 id="wasi-c-c-compilation-and-linking" tabindex="-1">WASI C/C++ compilation and linking <a class="header-anchor" href="#wasi-c-c-compilation-and-linking" aria-label="Permalink to “WASI C/C++ compilation and linking”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>-Oz</code></td><td>Optimizes native WebAssembly for minimum size.</td></tr><tr><td><code>-gline-tables-only</code></td><td>Keeps native source-line mappings for backtraces without full variable/type debug data.</td></tr><tr><td><code>-DNDEBUG</code></td><td>Removes C/C++ assertions.</td></tr><tr><td><code>-ffunction-sections -fdata-sections</code></td><td>Separates code and data so unused sections can be removed.</td></tr><tr><td><code>-DSTATIC_HERMES</code></td><td>Selects the Static Hermes implementation in the native JSI shim.</td></tr><tr><td><code>-mllvm -wasm-enable-sjlj</code> with <code>-lsetjmp</code></td><td>Provides the setjmp/longjmp lowering Hermes uses for JavaScript exceptions.</td></tr><tr><td><code>-mllvm -wasm-use-legacy-eh=false</code></td><td>Emits standard WebAssembly exception-handling instructions instead of the legacy ones. Every native compile and link step passes it, including the Hermes WASI library build.</td></tr><tr><td><code>-D_WASI_EMULATED_MMAN</code>, <code>-D_WASI_EMULATED_PROCESS_CLOCKS</code></td><td>Enables wasi-libc emulation for the POSIX calls Hermes needs.</td></tr><tr><td><code>-lwasi-emulated-mman</code>, <code>-lwasi-emulated-process-clocks</code></td><td>Links those wasi-libc emulation implementations.</td></tr><tr><td><code>-fwasm-exceptions</code></td><td>Keeps C++ exceptions for error handling in the JSI shim.</td></tr><tr><td><code>-w</code></td><td>Suppresses compiler diagnostics from the generated WIT C glue; used only when compiling <code>plugin.c</code>.</td></tr><tr><td><code>-mexec-model=reactor</code></td><td>Builds a reactor module whose plugin lifecycle is controlled by the component host.</td></tr><tr><td><code>-Wl,--gc-sections</code></td><td>Removes unreferenced sections from the final component.</td></tr><tr><td><code>-Wl,--strip-all</code></td><td>Removes symbol and debug tables from production components.</td></tr><tr><td><code>-Wl,--stack-first</code></td><td>Places the stack before static data so stack overflow is trapped.</td></tr><tr><td><code>-Wl,-z,stack-size=262144</code></td><td>Reserves the default 256 KiB WASI stack; <code>STATIC_HERMES_STACK_SIZE</code> changes it (a multiple of 16 bytes from 131072 through 4294967280, the largest 16-byte-aligned size below wasm32&#39;s 4 GiB address-space limit).</td></tr><tr><td><code>-lc++abi -lunwind</code></td><td>Links C++ ABI and unwinding support used by the JSI shim.</td></tr></tbody></table><p>See <a href="/pumpkin-plugins/guides/benchmarking">Benchmarking</a> for the comparison command, workload coverage, and report interpretation.</p><h2 id="api-and-platform-coverage" tabindex="-1">API and platform coverage <a class="header-anchor" href="#api-and-platform-coverage" aria-label="Permalink to “API and platform coverage”">​</a></h2><h3 id="pumpkin-api" tabindex="-1">Pumpkin API <a class="header-anchor" href="#pumpkin-api" aria-label="Permalink to “Pumpkin API”">​</a></h3><p><code>@pumpkin-plugins/build</code> resolves the Pumpkin API WIT from the installed API package&#39;s <code>wit.lock.json</code>, then supplies the pinned WIT directory alongside the WASI definitions. The first use of a lock digest fetches its upstream commit into the consumer&#39;s ignored cache. Each build generates the component ABI and the ignored <code>generated/api-enums.generated.h</code>. Component builds use the build package&#39;s source analysis to select API operations when it can determine the full set; direct codegen can select operations with <code>--api-methods</code>, and omission includes all imported API operations. Event conversion keeps complete payload fields for statically registered event types; dynamic or unresolved registrations retain every event case and payload field.</p><p>The runtime generator emits a JSI host function and a JavaScript facade for every operation in the pinned Pumpkin API WIT. A component includes the operations that source analysis selects, or all of them when the selection is unknown. If a selected operation uses a WIT type that has no adapter, the build fails and the error names the operation. Limits on the host side are documented separately; for example, the pinned Pumpkin host does not start custom AI goals, as the <a href="./docs/">runtime documentation</a> explains.</p><p>The generated Pumpkin API facades reject host calls during <code>on_unload</code>, except <code>scheduler.cancel-task</code>, which plugins need to stop scheduled callbacks. Cancel scheduled tasks and perform local cleanup during unload; other host calls remain unavailable. This guard prevents calls from re-entering the WASM store during shutdown.</p><h3 id="wasi" tabindex="-1">WASI <a class="header-anchor" href="#wasi" aria-label="Permalink to “WASI”">​</a></h3><p>Static Hermes reads the WIT directory prepared by <code>@pumpkin-plugins/build</code>. It validates every operation in an imported WASI interface, including operations the plugin does not use, and emits native adapters for selected operations. Component builds use the build package&#39;s source analysis when it can determine the full set; direct codegen can select operations with <code>--wasi-methods</code>, and omission includes all operations in the selected WASI imports. The imported interfaces are listed in the <a href="./docs/wasi#capability-bundles">WASI guide</a>. The build enables a feature-gated WIT operation when it is selected.</p><p>See the <a href="./docs/wasi">WASI guide</a> for supported imports and runtime limits.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/tools/static-hermes-runtime/docs/" target="_blank" rel="noreferrer">tool guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/tools/@pumpkin-plugins/static-hermes-runtime/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p>`,50)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};